package io.github.finalparadox.entity;
import io.github.finalparadox.ability.GlaivorusAbilityState;import io.github.finalparadox.item.WinterLamentItem;import io.github.finalparadox.registry.*;import net.minecraft.core.particles.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.protocol.Packet;import net.minecraft.network.protocol.game.ClientGamePacketListener;import net.minecraft.server.level.*;import net.minecraft.sounds.*;import net.minecraft.world.effect.*;import net.minecraft.world.entity.*;import net.minecraft.world.level.Level;import net.minecraft.world.phys.*;import net.minecraftforge.network.NetworkHooks;import java.util.*;
public final class FrostBreathEntity extends Entity{private UUID ownerId;public FrostBreathEntity(EntityType<FrostBreathEntity>t,Level l){super(t,l);noPhysics=true;noCulling=true;}public static boolean hasActive(ServerPlayer o){return !o.serverLevel().getEntitiesOfClass(FrostBreathEntity.class,o.getBoundingBox().inflate(128),e->o.getUUID().equals(e.ownerId)).isEmpty();}public static void spawn(ServerPlayer o){if(hasActive(o))return;FrostBreathEntity e=new FrostBreathEntity(ModEntities.FROST_BREATH.get(),o.serverLevel());e.ownerId=o.getUUID();e.setPos(o.position());o.serverLevel().addFreshEntity(e);o.serverLevel().playSound(null,o.blockPosition(),SoundEvents.SNOW_GOLEM_HURT,SoundSource.PLAYERS,1,0);}
 @Override protected void defineSynchedData(){}@Override public void tick(){super.tick();if(level().isClientSide)return;if(!(level() instanceof ServerLevel s)){discard();return;}ServerPlayer o=ownerId==null?null:s.getServer().getPlayerList().getPlayer(ownerId);if(o==null||!o.getMainHandItem().is(ModItems.WINTER_LAMENT.get())){discard();return;}setPos(o.position());int crystals=o.getPersistentData().getInt(WinterLamentItem.CRYSTALS_KEY);if(crystals<=0){discard();return;}Vec3 start=o.getEyePosition(),dir=o.getLookAngle().normalize();for(int i=0;i<25;i++){double d=1+o.getRandom().nextDouble()*6,r=d*.55,a=o.getRandom().nextDouble()*Math.PI*2;Vec3 right=dir.cross(new Vec3(0,1,0));if(right.lengthSqr()<.01)right=new Vec3(1,0,0);right=right.normalize();Vec3 up=right.cross(dir).normalize();Vec3 p=start.add(dir.scale(d)).add(right.scale(Math.cos(a)*r)).add(up.scale(Math.sin(a)*r));s.sendParticles(ParticleTypes.SNOWFLAKE,p.x,p.y,p.z,1,0,0,0,.02);}if((tickCount-1)%15!=0)return;o.getPersistentData().putInt(WinterLamentItem.CRYSTALS_KEY,crystals-1);o.displayClientMessage(net.minecraft.network.chat.Component.translatable("message.finalparadox.winter_lament.crystals",crystals-1),true);for(LivingEntity target:s.getEntitiesOfClass(LivingEntity.class,o.getBoundingBox().inflate(10),e->GlaivorusAbilityState.isHostileTarget(o,e)&&e.getPersistentData().getInt(FrozenPrisonEntity.FROZEN_TICKS)<=0)){Vec3 delta=target.getEyePosition().subtract(start);double distance=delta.length();if(distance>10||distance<.1||delta.normalize().dot(dir)<Math.cos(Math.toRadians(38)))continue;target.hurt(o.damageSources().playerAttack(o),8);target.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN,20,1),o);s.sendParticles(new ItemParticleOption(ParticleTypes.ITEM,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.ICE)),target.getX(),target.getY()+1,target.getZ(),30,0,0,0,.2);if(target.onGround()&&!isBoss(target)&&o.getRandom().nextFloat()<.4F)FrozenPrisonEntity.freeze(target,o);}if(crystals-1<=0)discard();}
 private static boolean isBoss(LivingEntity e){return e.getTags().contains("boss")||e instanceof net.minecraft.world.entity.boss.enderdragon.EnderDragon||e instanceof net.minecraft.world.entity.boss.wither.WitherBoss;}
 @Override protected void readAdditionalSaveData(CompoundTag t){if(t.hasUUID("Owner"))ownerId=t.getUUID("Owner");}@Override protected void addAdditionalSaveData(CompoundTag t){if(ownerId!=null)t.putUUID("Owner",ownerId);}@Override public Packet<ClientGamePacketListener>getAddEntityPacket(){return NetworkHooks.getEntitySpawningPacket(this);}}
